import{z as i,x as l,o as A,c as d,q as r,j as t,D as a,d as B,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"内核实践收束","description":"","frontmatter":{"title":"内核实践收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/osk-map.md","filePath":"cs/osk-map.md","lastUpdated":1791063341000}'),p={name:"cs/osk-map.md"};function D(F,E,C,m,c,u){const s=l("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="内核实践收束" tabindex="-1">内核实践收束 <a class="header-anchor" href="#内核实践收束" aria-label="Permalink to &quot;内核实践收束&quot;">​</a></h1><div class="epigraph"><p>内核的全部复杂度长在同一句承诺上：上层看见的是对象与调用，底下兑现它的是栈、表与队列。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Arpaci-Dusseau, OSTEP 整理</footer></div><p><a href="/cs/osk-kernel-debugging">上一课</a>把出错之后的三条路补齐。本课程到此收束：本课把六课收成一条装配主线与几条不变量，交代哪些部分刻意留给了主干课。本课程回答的始终是实现面——策略与语义在主干课（调度、置换、文件、接口各有专课），本课程给的是把那些零件总装起来的骨架；两者合起来，「操作系统」才从名词变成可读、可改、可查的机器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的问题是：六课合起来，你获得了主干课没给的什么？答案不是多认了几个结构体名，而是一张总装图：一次缺页、一个 write、一条中断、一次上下文切换进来，内核里各自发生什么、在哪个对象上留下什么状态、从哪两个入口进来。只会背零件图的人，改动一处就不知道会断在哪里——这不只是初学者的困境，主干课留下的正是这个缺口：零件各有专课，装配无人认领。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>六课折成一条主线。<strong>进程与调度</strong>立「执行流」：控制块挂一切，切换只换页表基址与内核栈；<strong>虚拟内存</strong>立「地址」：区间声明、页表现挂、反向映射连回物理页；<strong>文件系统</strong>立「数据」：VFS 对象解耦盘上布局，页缓存与日志分守两层一致性；<strong>系统调用</strong>立「同步入口」：五步固定序；<strong>中断与驱动</strong>立「异步入口」：probe 注册一切、顶半部只做最少；<strong>调试</strong>立「失效面」：事后、在线、重现三路。贯穿的不变量四条：进入内核必经两个入口之一；跨边界的数据必须显式拷贝；执行上下文决定能调用什么（能睡的才许调度，顶半部不许睡）；一切注册皆有对称拆除。</p><p><span class="marginnote">术语翻译：上下文切换「只换页表基址与内核栈」——页表基址是一个寄存器，它决定整套地址翻译（换进程等于换一张地图）；内核栈是进程进内核干活时的工作台（换进程连桌子一起换）。控制块上挂着这两样的指针，切换就是照单换装。</span></p>',8)),(A(),t(o,null,{default:a(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E7%94%A8%E6%88%B7%E6%80%81%22%5D%20--%3E%20SYNC%5B%22%E5%90%8C%E6%AD%A5%E5%85%A5%E5%8F%A3%EF%BC%9A%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E4%BA%94%E6%AD%A5%22%5D%0A%20%20UP%20--%3E%20ASYNC%5B%22%E5%BC%82%E6%AD%A5%E5%85%A5%E5%8F%A3%EF%BC%9A%E4%B8%AD%E6%96%AD%E4%B8%8E%E4%B8%8B%E5%8D%8A%E9%83%A8%22%5D%0A%20%20SYNC%20--%3E%20CORE%5B%22%E6%A0%B8%E5%BF%83%E5%AF%B9%E8%B1%A1%EF%BC%9A%E6%8E%A7%E5%88%B6%E5%9D%97%E4%B8%8E%E5%9C%B0%E5%9D%80%E7%A9%BA%E9%97%B4%22%5D%0A%20%20ASYNC%20--%3E%20CORE%0A%20%20CORE%20--%3E%20SCHED%5B%22%E8%B0%83%E5%BA%A6%EF%BC%9A%E8%BF%90%E8%A1%8C%E9%98%9F%E5%88%97%E4%B8%8E%E5%88%87%E6%8D%A2%22%5D%0A%20%20CORE%20--%3E%20VM%5B%22%E8%99%9A%E5%AD%98%EF%BC%9A%E5%8C%BA%E9%97%B4%E3%80%81%E9%A1%B5%E8%A1%A8%E4%B8%8E%E5%8F%8D%E5%90%91%E6%98%A0%E5%B0%84%22%5D%0A%20%20SYNC%20--%3E%20FS%5B%22%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%EF%BC%9AVFS%E3%80%81%E9%A1%B5%E7%BC%93%E5%AD%98%E4%B8%8E%E6%97%A5%E5%BF%97%22%5D%0A%20%20DBG%5B%22%E8%B0%83%E8%AF%95%EF%BC%9A%E4%BA%8B%E5%90%8E%E3%80%81%E5%9C%A8%E7%BA%BF%E3%80%81%E9%87%8D%E7%8E%B0%22%5D%20-.-%3E%20SYNC%0A%20%20DBG%20-.-%3E%20ASYNC%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"四条不变量各堵一个已知失效。只认两个入口，堵「绕过校验直进内核」的捷径——任何绕路都意味着绕过五步里的检查；显式拷贝堵内核态裸解引用与检查-使用之间的竞态；上下文定可调用集堵「中断里睡眠」的挂死——它不能被调度出去，因为它不在调度器的任何队列里；对称拆除堵卸载后的悬空注册——还在表里的回调指向已释放的代码，下一次中断就是一次任意跳转。四条合起来是同一件事：让实现错误在装配点当场暴露，而不是埋进时序里等偶发复现。主干与深钻的分界也在此收口：再往下走就是源码本身——本课程给的是读源码时手里那张总装图，不是源码的替代品。",-1)),(A(),t(o,null,{default:a(()=>[n(s,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV1%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%3A%20%E5%8F%AA%E8%AE%A4%E4%B8%A4%E4%B8%AA%E5%85%A5%E5%8F%A3%22%5D%20--%3E%20F1%5B%22%E5%A0%B5%3A%20%E7%BB%95%E8%BF%87%E6%A0%A1%E9%AA%8C%E7%9B%B4%E8%BF%9B%E5%86%85%E6%A0%B8%22%5D%0A%20%20INV2%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%3A%20%E8%B7%A8%E8%BE%B9%E7%95%8C%E6%98%BE%E5%BC%8F%E6%8B%B7%E8%B4%9D%22%5D%20--%3E%20F2%5B%22%E5%A0%B5%3A%20%E8%A3%B8%E8%A7%A3%E5%BC%95%E7%94%A8%E4%B8%8E%E6%A3%80%E6%9F%A5%E5%90%8E%E5%A4%8D%E7%94%A8%E7%AB%9E%E6%80%81%22%5D%0A%20%20INV3%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%3A%20%E4%B8%8A%E4%B8%8B%E6%96%87%E5%AE%9A%E5%8F%AF%E8%B0%83%E7%94%A8%E9%9B%86%22%5D%20--%3E%20F3%5B%22%E5%A0%B5%3A%20%E4%B8%AD%E6%96%AD%E9%87%8C%E7%9D%A1%E7%9C%A0%2C%20CPU%20%E6%8C%82%E6%AD%BB%22%5D%0A%20%20INV4%5B%22%E4%B8%8D%E5%8F%98%E9%87%8F%3A%20%E6%B3%A8%E5%86%8C%E5%BF%85%E5%AF%B9%E7%A7%B0%E6%8B%86%E9%99%A4%22%5D%20--%3E%20F4%5B%22%E5%A0%B5%3A%20%E5%8D%B8%E8%BD%BD%E5%90%8E%E6%82%AC%E7%A9%BA%E5%9B%9E%E8%B0%83%E8%A2%AB%E4%B8%AD%E6%96%AD%E8%B0%83%E7%94%A8%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">直觉类比：注册像在门卫室留了「快递放我家」的条子，对称拆除就是搬走时撕掉条子。忘了撕，房子拆了条子还在——下一个快递员（中断）照条子把包裹塞进已拆的房址，等于把货交给了一块随机内存。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程刻意不覆盖的三块都在紧邻位置：性能调优与观测体系是观测课的对象；具体设备与总线协议是接口课的对象；虚拟化与容器在主干隔离单元。最后一点要说诚实：总装图不等于可维护性——内核代码库的复杂度大头在并发、历史包袱与跨架构抽象，六课的骨架帮你读得懂路径，读不透全部权衡；把骨架当成「内核就是这么简单」是本课程能造成的最大误读。骨架的价值在方向：知道每段代码在装配图上的位置，才知道去哪查、改哪会断。</p><p><span class="marginnote">常见误区：读完骨架容易产生「内核不过如此」的错觉。真正的复杂度大头在并发交错、几十年的历史包袱与跨架构抽象里；骨架给你的是地图，不是地形本身——知道改哪会断，不等于知道每处为什么这样设计。</span></p><p><span class="marginnote">自检一题足够：沿一次完整的 write 写出它经过的每一层——陷入、分派、VFS 操作表、页缓存、回写、日志、bio、驱动、中断完成。能在十分钟内不查资料画全这条链，本课程的目的就达到了。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>六课一条装配主线：执行流、地址、数据、同步入口、异步入口、失效面。</li><li>四条不变量：两个入口、显式拷贝、上下文定可调用集、注册必对称拆除。</li><li>主干给零件图，本课程给总装图；每条不变量都堵一个已知的装配失效。</li><li>总装图不等于内核的全部复杂度；它的价值是给源码阅读定位方向。</li><li>本课程到此收束；出处：Tanenbaum and Bos, <em>Modern Operating Systems</em>；Arpaci-Dusseau, <em>OSTEP</em>。</li></ul>',7))])}const S=i(p,[["render",D]]);export{g as __pageData,S as default};
